import React, { useState } from 'react';
import { Map, MapPin, ChevronRight, ChevronLeft, Search, Box, Layers } from 'lucide-react';

const AreasZonesTab = () => {
  const [viewLevel, setViewLevel] = useState('ZONES'); 
  const [selectedZone, setSelectedZone] = useState(null);
  const [selectedArea, setSelectedArea] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  const zoneData = [
    {
      id: 'Z-1', name: 'NORTH_SECTOR', code: 'NS-ALPHA', color: '#AB1717',
      areas: [
        { id: 'A-1', name: 'Hillside Drive', location: 'North Ridge', code: 'HSD-44', bins: ['BN-401', 'BN-405', 'BN-409'] },
        { id: 'A-2', name: 'University Road', location: 'East Campus', code: 'URD-12', bins: ['BN-502', 'BN-503'] }
      ]
    },
    {
      id: 'Z-2', name: 'CENTRAL_HUB', code: 'CH-BRAVO', color: '#CAD23C',
      areas: [
        { id: 'A-3', name: 'Main Square', location: 'Downtown', code: 'MSQ-01', bins: ['BN-101', 'BN-102'] }
      ]
    }
  ];

  const displayData = viewLevel === 'ZONES' 
    ? zoneData.filter(z => z.name.includes(searchQuery.toUpperCase()))
    : selectedZone?.areas.filter(a => a.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div className="w-full animate-slot flex flex-col gap-10">

      {/* HEADER: High-Contrast Navigation */}
      <div className="flex justify-between items-center border-b-4 border-[#47510B] pb-8">
        <div className="flex items-center gap-6">
          {viewLevel !== 'ZONES' && (
            <button 
              onClick={() => setViewLevel(viewLevel === 'BINS' ? 'AREAS' : 'ZONES')} 
              className="bg-[#47510B] text-white p-2 hover:bg-[#AB1717] transition-all rounded-sm shadow-[4px_4px_0_0_#CAD23C]"
            >
              <ChevronLeft size={24} strokeWidth={3} />
            </button>
          )}
          <div>
            <h2 className="text-4xl font-[1000] italic text-[#47510B] tracking-tighter uppercase leading-none">
              {viewLevel === 'ZONES' ? 'SECTORS' : viewLevel === 'AREAS' ? selectedZone.name : selectedArea.name}
            </h2>
            <div className="h-1.5 w-20 bg-[#AB1717] mt-2" />
          </div>
        </div>
        <div className="relative group">
          <Search className="absolute left-3 top-3 text-[#AB1717]" size={20} />
          <input 
            type="text" placeholder="FILTER_SYSTEM..." 
            className="bg-[#FDFAD8] border-2 border-[#47510B] py-3 pl-12 pr-4 text-xs font-black uppercase outline-none focus:ring-4 focus:ring-[#CAD23C]/30 w-48 md:w-72 shadow-[4px_4px_0_0_#47510B]"
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* LEVEL 1: ZONES (Visual Stripe List) */}
      {viewLevel === 'ZONES' && (
        <div className="flex flex-col gap-4">
          {displayData.map(zone => (
            <div key={zone.id} onClick={() => {setSelectedZone(zone); setViewLevel('AREAS');}}
              className="group flex justify-between items-center bg-white border-2 border-[#47510B] p-6 cursor-pointer hover:translate-x-3 transition-all relative overflow-hidden shadow-[6px_6px_0_0_#47510B]">
              <div className="absolute left-0 top-0 h-full w-3 bg-[#AB1717]" />
              <div className="flex flex-col gap-1 ml-4">
                <span className="text-[10px] font-black text-[#AB1717] tracking-widest uppercase">{zone.code}</span>
                <h3 className="text-2xl font-black text-[#47510B] italic">{zone.name}</h3>
              </div>
              <div className="flex items-center gap-10">
                <div className="text-right">
                  <p className="text-[10px] font-black opacity-30 uppercase">Areas_Active</p>
                  <p className="text-2xl font-black text-[#47510B] leading-none">{zone.areas.length}</p>
                </div>
                <ChevronRight size={32} className="text-[#AB1717] opacity-20 group-hover:opacity-100 group-hover:translate-x-2 transition-all" />
              </div>
            </div>
          ))}
        </div>
      )}

      {/* LEVEL 2: AREAS (Information Density) */}
      {viewLevel === 'AREAS' && (
        <div className="flex flex-col gap-4">
          {displayData.map(area => (
            <div key={area.id} onClick={() => {setSelectedArea(area); setViewLevel('BINS');}}
              className="group grid grid-cols-1 md:grid-cols-4 items-center bg-white border-2 border-[#47510B] hover:bg-[#CAD23C]/10 transition-all cursor-pointer shadow-[6px_6px_0_0_#AB1717] overflow-hidden">
              <div className="bg-[#47510B] p-6 flex flex-col items-center justify-center text-[#CAD23C]">
                <span className="text-[8px] font-black uppercase opacity-60 mb-1">Area_Code</span>
                <span className="text-lg font-black italic tracking-tighter">{area.code}</span>
              </div>
              <div className="p-6 md:col-span-2">
                <h4 className="text-xl font-black text-[#47510B] uppercase italic">{area.name}</h4>
                <div className="flex items-center gap-2 mt-1 text-[#AB1717]">
                  <MapPin size={12} strokeWidth={3} />
                  <span className="text-[10px] font-black uppercase tracking-widest">{area.location}</span>
                </div>
              </div>
              <div className="p-6 flex items-center justify-between md:justify-end gap-10 border-t-2 md:border-t-0 md:border-l-2 border-[#47510B]/10">
                <span className="text-xl font-black text-[#47510B]">{area.bins.length} UNITS</span>
                <ChevronRight size={24} className="text-[#AB1717]" />
              </div>
            </div>
          ))}
        </div>
      )}

      {/* LEVEL 3: BINS (Vibrant Hardware Nodes) */}
      {viewLevel === 'BINS' && (
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-6">
          {selectedArea.bins.map(binId => (
            <div key={binId} className="flex flex-col items-center gap-4 p-8 bg-white border-4 border-[#47510B] hover:bg-[#CAD23C] hover:-translate-y-2 transition-all group shadow-[6px_6px_0_0_#AB1717]">
              <div className="bg-[#AB1717] p-2 rounded-sm group-hover:bg-[#47510B] transition-colors">
                <Box size={20} className="text-white" />
              </div>
              <span className="text-sm font-[1000] text-[#47510B] font-mono border-b-2 border-[#AB1717] pb-1">{binId}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default AreasZonesTab;
